/* SCP0096_registration.sql — 사내 현행 메타 미러(비파괴·멱등) · 2026-10-20 사람 재작성
 * 2026-10-20 추가: BLOCK 3-b (WORKING_TIME_DEFAULT INPUT_TP_CD 'O' 정합 UPDATE — 유일한 기존행 갱신, 멱등·대상 1컬럼 1속성).
 * 원 생성: tools/Harness/gen-register-sql.js 2026-10-19 (register.json). 생성본은 ACTION 배선 'PKG_SCP0096.P_'(프로시저명 공란) ·
 *   SEARCH → P_DM0003_GET_BUCKET_TYPE_CODE 로 사내 현행(P_SCP0096_GET)과 달랐고(DoD B23), DELETE 후 INSERT 라 사내 MNU_BTN_MPG_M 5행을
 *   2행으로 덮었다(2026-10-19 드라이런 ROLLBACK). → 7영역 전부 사내 현행값 그대로 + NOT EXISTS / WHEN NOT MATCHED 로 재작성.
 *   사내(ZIOUI1)에서 실행하면 0행 변경이 정상이고, 클라우드 등 부재 환경에서는 부재분만 생성된다. 기존 행 UPDATE·DELETE 없음.
 * 원천(hook #152 착수 재조회): ZIOUI1 SCM_MGR 2026-10-20 07:49:39 — _artifacts/_diagnostics/SCP0096_SUPP_20261020/probe_dayrange_meta.out.md
 *   PKG_SCP0096 PACKAGE/BODY VALID LAST_DDL 2026-10-19 22:53:27 · PKG_COM0000 BODY VALID 2026-10-13 17:04:52
 * 선행: PKG_SCP0096(P_SCP0096_GET/SAVE + 2026-10-19 이식 P_DM0003_GET_BUCKET_TYPE_CODE/P_SCP0009_GET_SHEET_CALENDAR_3SPAN) · PKG_COM0000 ·
 *   GTT GT_SCP0096_PIVOT (클라우드 이관 패키지에 DDL 동봉 — feedback_deploy_package_gtt_type_ddl)
 * 실행: python tools/DbConn/run_sql.py <이 파일> [--commit]  (SQL*Plus/SQLcl 도 가능). COMMIT 은 BLOCK 8 결과 확인 후.
 * 등록 SQL 재생성 금지: gen-register-sql.js 로 다시 만들면 DELETE+INSERT 생성본으로 회귀한다(register.json note 참조).
 */
SET DEFINE ON
SET SERVEROUTPUT ON SIZE UNLIMITED
DEFINE V_MENU_ID     = 'SCP0096'
DEFINE V_MENU_MSG_ID = 'MNU_SCP0096'
DEFINE V_MENU_URL    = 'shipment-working-day-osp'
DEFINE V_PKG_NM      = 'PKG_SCP0096'
DEFINE V_USER_ID     = 'harness'

-- BLOCK 1: i18n 메뉴명 — 사내는 MNU_SCP0096 기등록(재사용). 부재 환경만 INSERT … NOT EXISTS (hook #140: MSG_M 은 INSERT NOT EXISTS 전용, MERGE/UPDATE ⛔)
--   라벨 = Doc/tobefacts/db/menu.csv mnu_desc 'Shipment Working Day (OSP)'. KO/CN 번역은 사내 기존값 우선(여기선 부재 시 EN 동일 — i18n KO=EN 룰).
INSERT INTO SCM_ADM_MSG_M (MSG_ID, LANG_CD, MSG_NM, MSG_TP_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT '&V_MENU_MSG_ID', L.LANG_CD, 'Shipment Working Day (OSP)', 'MNU', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE
  FROM (SELECT 'KO' AS LANG_CD FROM DUAL UNION ALL SELECT 'EN' FROM DUAL UNION ALL SELECT 'CN' FROM DUAL) L
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_MSG_M M WHERE M.MSG_ID = '&V_MENU_MSG_ID' AND M.LANG_CD = L.LANG_CD);

-- BLOCK 2: PROC_M — ALL_ARGUMENTS 동적 등록, NOT EXISTS(PROC_NM+SORT_ORD) 멱등. 사내 현행 21행(2+4+6+9) + 공용 PKG_COM0000 2 프로시저(기등록) 무변경.
--   COL_NM 규칙 = 사내 현행과 동일(IN → camelCase(P_ 제거) / OUT → 소문자 · O_RESULT_CURSOR → PROC_RESULT) — FE filter 키의 정본(DoD B22).
DECLARE
  v_n NUMBER; v_rows NUMBER;
BEGIN
  FOR p IN (SELECT 'PKG_SCP0096' AS PKG, 'P_SCP0096_GET_SHIPMENT_WORKING_DAY_OSP'  AS OBJ FROM DUAL UNION ALL
            SELECT 'PKG_SCP0096',        'P_SCP0096_SAVE_SHIPMENT_WORKING_DAY_OSP'        FROM DUAL UNION ALL
            SELECT 'PKG_SCP0096',        'P_DM0003_GET_BUCKET_TYPE_CODE'                  FROM DUAL UNION ALL
            SELECT 'PKG_SCP0096',        'P_SCP0009_GET_SHEET_CALENDAR_3SPAN'             FROM DUAL UNION ALL
            SELECT 'PKG_COM0000',        'P_SCP0009_GET_SHEET_CALENDAR_3SPAN'             FROM DUAL UNION ALL
            SELECT 'PKG_COM0000',        'P_SCM0001_GET_SCP_MONTH_PERIOD'                 FROM DUAL) LOOP
    v_n := 0;
    FOR r IN (SELECT ARGUMENT_NAME, IN_OUT, DATA_TYPE, POSITION
                FROM ALL_ARGUMENTS
               WHERE OWNER = 'SCM_MGR' AND PACKAGE_NAME = p.PKG AND OBJECT_NAME = p.OBJ
                 AND DATA_LEVEL = 0 AND ARGUMENT_NAME IS NOT NULL
               ORDER BY POSITION) LOOP
      v_n := v_n + 1;
      INSERT INTO SCM_ADM_PROC_M (PROC_NM, COL_NM, COL_TP_CD, DATA_TP_CD, SORT_ORD, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      SELECT p.PKG || '.' || p.OBJ,
             CASE WHEN r.IN_OUT LIKE '%OUT%' THEN LOWER(r.ARGUMENT_NAME) ELSE PKG_NSCM_UI_COMM.FN_TO_CAMEL_CASE(REGEXP_REPLACE(r.ARGUMENT_NAME, '^P_', '')) END,
             CASE WHEN r.IN_OUT LIKE '%OUT%' THEN 'OUT' ELSE 'IN' END,
             CASE WHEN r.ARGUMENT_NAME = 'O_RESULT_CURSOR' THEN 'PROC_RESULT' ELSE PKG_NSCM_UI_COMM.FN_GET_SYSTEM_DATA_TP(r.DATA_TYPE) END,
             v_n, '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE
        FROM DUAL
       WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_PROC_M M WHERE M.PROC_NM = p.PKG || '.' || p.OBJ AND M.SORT_ORD = v_n);
    END LOOP;
    SELECT COUNT(*) INTO v_rows FROM SCM_ADM_PROC_M M WHERE M.PROC_NM = p.PKG || '.' || p.OBJ;
    IF v_n = 0 THEN
      DBMS_OUTPUT.PUT_LINE('  WARN ' || p.PKG || '.' || p.OBJ || ' 가 ALL_ARGUMENTS 에 없음(PKG 미배포) — PKG 배포 후 이 SQL 재실행');
    ELSE
      DBMS_OUTPUT.PUT_LINE('  OK ' || p.PKG || '.' || p.OBJ || ' ALL_ARGUMENTS ' || v_n || '건 → PROC_M 행수 ' || v_rows);
    END IF;
  END LOOP;
END;
/

-- BLOCK 3: SHEET_COLUMNS — 사내 현행 6행 미러(2026-10-20 실측값: 라벨 'Div' · FIXED '-'/'Y' · USER_SELECTABLE '-' · DIVISION_ID NULL ·
--   WORKING_TIME_DEFAULT INPUT_TP_CD 'O'(ZIONEX 2026-09-25 변경) · 나머지 'S'). NOT EXISTS(PROGRAM_ID+SHEET_NAME+COLUMN_NAME) — 기존 행 무변경.
--   '-' 는 기존 데이터 값 그대로 보존(센티널 신규 작성 아님 — #119 §0.5 원래 '-' 데이터 유지).
DECLARE
    v_col_json CLOB := '[
        {"sht_nm":"Shipment Working Day OSP","col_nm":"DIVISION_ID","col_lbl":"Div","sort_ord":1,"fixed":"-","col_wth":50,"align":"C","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"S"},
        {"sht_nm":"Shipment Working Day OSP","col_nm":"PLANT_SITE_ID","col_lbl":"Plant Site ID","sort_ord":2,"fixed":"-","col_wth":100,"align":"L","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"S"},
        {"sht_nm":"Shipment Working Day OSP","col_nm":"PLANT_SITE_NAME","col_lbl":"Plant Site","sort_ord":3,"fixed":"-","col_wth":130,"align":"L","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"S"},
        {"sht_nm":"Shipment Working Day OSP","col_nm":"WORKING_TIME_DEFAULT","col_lbl":"Working Time Default","sort_ord":4,"fixed":"-","col_wth":85,"cell_tp":"FPNumber","scale":2,"align":"R","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"O"},
        {"sht_nm":"Shipment Working Day OSP","col_nm":"LAST_INPUT_DATE","col_lbl":"Last Input Date","sort_ord":5,"fixed":"-","col_wth":100,"align":"C","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"S"},
        {"sht_nm":"Shipment Working Day OSP","col_nm":"MEASURE","col_lbl":"Measure","sort_ord":6,"fixed":"Y","col_wth":140,"align":"L","visible":"Y","default_f":"Y","usr_sel":"-","input_tp":"S"}
    ]';
BEGIN
    INSERT INTO SCM_MST_SHEET_COLUMNS (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, SMALL_CLASS_LABEL_NAME, LARGE_CLASS_LABEL_NAME, FIXED_FLAG, COLUMN_WIDTH,
        CELL_CONTROL_OBJECT_TYPE_CODE, CELL_COMBO_DATA_TYPE, DATA_SCALE_NUMBER, DATA_MAX_LENGTH, HORIZONTAL_ALIGN_CODE, UPPERCASE_APPLY_FLAG, VISIBLE_FLAG, DEFAULT_FLAG, USER_SELECTABLE_FLAG, VALID_YN, DIVISION_ID, INPUT_TP_CD,
        CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    SELECT '&V_MENU_ID', jt.SHT_NM, jt.COL_NM, jt.COL_LBL, jt.SORT_ORD, jt.SMALL_CLS, jt.LARGE_CLS, NVL(jt.FIXED, '-'), NVL(jt.COL_WTH, 100), jt.CELL_TP, jt.CELL_CBO, jt.SCALE, NVL(jt.MAX_LEN, 200), NVL(jt.ALIGN, 'L'), NVL(jt.UPPER, 'N'), NVL(jt.VISIBLE, 'Y'), NVL(jt.DEFAULT_F, 'Y'), NVL(jt.USR_SEL, '-'), 'Y', jt.DIV_ID, NVL(jt.INPUT_TP, 'S'), '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE
    FROM JSON_TABLE(v_col_json, '$[*]' COLUMNS (SHT_NM VARCHAR2(50 CHAR) PATH '$.sht_nm', COL_NM VARCHAR2(100 CHAR) PATH '$.col_nm', COL_LBL VARCHAR2(200 CHAR) PATH '$.col_lbl', SORT_ORD NUMBER PATH '$.sort_ord', SMALL_CLS VARCHAR2(100 CHAR) PATH '$.small_cls', LARGE_CLS VARCHAR2(100 CHAR) PATH '$.large_cls', FIXED VARCHAR2(1 CHAR) PATH '$.fixed', COL_WTH NUMBER PATH '$.col_wth', CELL_TP VARCHAR2(50 CHAR) PATH '$.cell_tp', CELL_CBO VARCHAR2(100 CHAR) PATH '$.cell_cbo', SCALE NUMBER PATH '$.scale', MAX_LEN NUMBER PATH '$.max_len', ALIGN VARCHAR2(1 CHAR) PATH '$.align', UPPER VARCHAR2(1 CHAR) PATH '$.upper', VISIBLE VARCHAR2(1 CHAR) PATH '$.visible', DEFAULT_F VARCHAR2(1 CHAR) PATH '$.default_f', USR_SEL VARCHAR2(1 CHAR) PATH '$.usr_sel', DIV_ID VARCHAR2(100 CHAR) PATH '$.div_id', INPUT_TP VARCHAR2(50 CHAR) PATH '$.input_tp')) jt
    WHERE NOT EXISTS (SELECT 1 FROM SCM_MST_SHEET_COLUMNS C WHERE C.PROGRAM_ID = '&V_MENU_ID' AND C.SHEET_NAME = jt.SHT_NM AND C.COLUMN_NAME = jt.COL_NM);
    DBMS_OUTPUT.PUT_LINE('[BLOCK 3] SCM_MST_SHEET_COLUMNS 신규 ' || SQL%ROWCOUNT || ' 행 (사내 기등록 6행이면 0)');
END;
/

-- BLOCK 3-b: SHEET_COLUMNS 편집속성 정합 — WORKING_TIME_DEFAULT INPUT_TP_CD = 'O' (사내 현행 ZIONEX 2026-09-25 · AS-IS 는 코드로 개방 .cs:163 SetReNumerCellType).
--   FE Grid 가 2026-10-20 부터 편집 가부를 SHEET_COLUMNS.INPUT_TP_CD 단일 원천으로 판정하므로(feedback_input_tp_cd_meta_over_hardcoded_editlock),
--   BLOCK 3 의 NOT EXISTS 가 건너뛰는 '기존 행이 S 로 남은 환경'(클라우드 등)만 'O' 로 맞춘다. 사내는 이미 'O' 라 0행. 다른 컬럼·속성은 건드리지 않는다(멱등).
UPDATE SCM_MST_SHEET_COLUMNS
   SET INPUT_TP_CD = 'O', LAST_UPDATED_BY = '&V_USER_ID', LAST_UPDATE_DATE = SYSDATE
 WHERE PROGRAM_ID = '&V_MENU_ID' AND SHEET_NAME = 'Shipment Working Day OSP' AND COLUMN_NAME = 'WORKING_TIME_DEFAULT'
   AND NVL(INPUT_TP_CD, 'S') <> 'O';

-- BLOCK 4: MENU — 사내 현행(상위 Supply_Master · 레벨 3 · 정렬 96 · ROUTE_PATH supply/supply-master/shipment-working-day-osp). 부재 시에만 INSERT(기존 행 UPDATE 없음).
MERGE INTO SCM_ADM_MNU_M T USING (SELECT '&V_MENU_ID' AS MNU_ID FROM DUAL) S ON (T.MNU_ID = S.MNU_ID)
WHEN NOT MATCHED THEN INSERT (MNU_ID, UPPR_MNU_ID, MNU_LV_NO, MNU_MSG_ID, MNU_URL, SORT_ORD, USE_YN, MNU_TP_CD, ROUTE_PATH, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES ('&V_MENU_ID', 'Supply_Master', 3, '&V_MENU_MSG_ID', '&V_MENU_URL', 96, 'Y', 'SCREEN', 'supply/supply-master/shipment-working-day-osp', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);

-- BLOCK 5: API (사내 현행 4행 — API_ID·API_TP_CD·API_URL 실측 그대로. 공용 2건(SCP0009/SCM0001)은 타 화면과 공유되므로 절대 DELETE 금지)
MERGE INTO SCM_ADM_API_M T USING (SELECT 'P_SCP0096_GET' AS API_ID FROM DUAL) S ON (T.API_ID = S.API_ID)
WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES ('P_SCP0096_GET', 'PROC_SELECT', NULL, 'SCP0096 Shipment Working Day OSP SEARCH', 'PKG_SCP0096.P_SCP0096_GET_SHIPMENT_WORKING_DAY_OSP', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);
MERGE INTO SCM_ADM_API_M T USING (SELECT 'P_SCP0096_SAVE' AS API_ID FROM DUAL) S ON (T.API_ID = S.API_ID)
WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES ('P_SCP0096_SAVE', 'PROC_SAVE', NULL, 'SCP0096 Shipment Working Day OSP SAVE', 'PKG_SCP0096.P_SCP0096_SAVE_SHIPMENT_WORKING_DAY_OSP', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);
MERGE INTO SCM_ADM_API_M T USING (SELECT 'SCP0009_SHEET_CALENDAR_3SPAN_GET' AS API_ID FROM DUAL) S ON (T.API_ID = S.API_ID)
WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES ('SCP0009_SHEET_CALENDAR_3SPAN_GET', 'PROC_SELECT', NULL, 'SCP0009 Sheet Calendar 3SPAN (common)', 'PKG_COM0000.P_SCP0009_GET_SHEET_CALENDAR_3SPAN', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);
MERGE INTO SCM_ADM_API_M T USING (SELECT 'SCM0001_SCP_MONTH_PERIOD_GET' AS API_ID FROM DUAL) S ON (T.API_ID = S.API_ID)
WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES ('SCM0001_SCP_MONTH_PERIOD_GET', 'PROC_SELECT', NULL, 'SCM0001 SCP Month Period / dayRange (common)', 'PKG_COM0000.P_SCM0001_GET_SCP_MONTH_PERIOD', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);

-- BLOCK 6: MNU_BTN_MPG (사내 현행 5행 — 시트×버튼 → API. EDIT 는 API 없음(권한 게이트 전용 — FE canEdit=hasButton('EDIT')). INSERT/DELETE 정의 없음 = FE hotkeyConfig false)
MERGE INTO SCM_ADM_MNU_BTN_MPG_M T
USING (SELECT '&V_MENU_ID' AS MNU_ID, SHT_NM, MNU_BTN_CD, API_ID FROM (
         SELECT 'Shipment Working Day OSP' AS SHT_NM, 'EDIT'   AS MNU_BTN_CD, CAST(NULL AS VARCHAR2(100)) AS API_ID FROM DUAL UNION ALL
         SELECT 'Shipment Working Day OSP',           'SAVE',                  'P_SCP0096_SAVE'                       FROM DUAL UNION ALL
         SELECT 'Shipment Working Day OSP',           'SEARCH',                'P_SCP0096_GET'                        FROM DUAL UNION ALL
         SELECT 'calendar',                           'SEARCH',                'SCP0009_SHEET_CALENDAR_3SPAN_GET'     FROM DUAL UNION ALL
         SELECT 'dayRange',                           'SEARCH',                'SCM0001_SCP_MONTH_PERIOD_GET'         FROM DUAL)) S
   ON (T.MNU_ID = S.MNU_ID AND T.SHT_NM = S.SHT_NM AND T.MNU_BTN_CD = S.MNU_BTN_CD)
WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
  VALUES (S.MNU_ID, S.SHT_NM, S.MNU_BTN_CD, S.API_ID, 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);

-- BLOCK 7: 그룹 권한 — 사내 현행 4그룹(ADMIN · SCM PI Admin · SCM Viewer · SCP Planner) 메뉴 + 5버튼 전부 Y (2026-10-20 실측 20행). NOT EXISTS.
INSERT INTO SCM_ADM_USER_GR_MNU_MPG_M (USER_GR_ID, MNU_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT G.USER_GR_ID, '&V_MENU_ID', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE
  FROM (SELECT 'ADMIN' AS USER_GR_ID FROM DUAL UNION ALL SELECT 'SCM PI Admin' FROM DUAL UNION ALL SELECT 'SCM Viewer' FROM DUAL UNION ALL SELECT 'SCP Planner' FROM DUAL) G
 WHERE EXISTS (SELECT 1 FROM SCM_ADM_USER_GR_M U WHERE U.USER_GR_ID = G.USER_GR_ID)
   AND NOT EXISTS (SELECT 1 FROM SCM_ADM_USER_GR_MNU_MPG_M E WHERE E.USER_GR_ID = G.USER_GR_ID AND E.MNU_ID = '&V_MENU_ID');
INSERT INTO SCM_ADM_USER_GR_MNU_BTN_MPG_M (USER_GR_ID, MNU_ID, SHT_NM, MNU_BTN_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT G.USER_GR_ID, B.MNU_ID, B.SHT_NM, B.MNU_BTN_CD, 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE
  FROM SCM_ADM_MNU_BTN_MPG_M B
 CROSS JOIN (SELECT 'ADMIN' AS USER_GR_ID FROM DUAL UNION ALL SELECT 'SCM PI Admin' FROM DUAL UNION ALL SELECT 'SCM Viewer' FROM DUAL UNION ALL SELECT 'SCP Planner' FROM DUAL) G
 WHERE B.MNU_ID = '&V_MENU_ID'
   AND EXISTS (SELECT 1 FROM SCM_ADM_USER_GR_M U WHERE U.USER_GR_ID = G.USER_GR_ID)
   AND NOT EXISTS (SELECT 1 FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M E
                    WHERE E.USER_GR_ID = G.USER_GR_ID AND E.MNU_ID = B.MNU_ID AND E.SHT_NM = B.SHT_NM AND E.MNU_BTN_CD = B.MNU_BTN_CD);

-- BLOCK 8: 검증 — 기대값(사내 2026-10-20 실측): MENU 1 · PROC_M(PKG_SCP0096) 21 · SHEET_COLUMNS 6 · API 4 · MNU_BTN_MPG 5 · GROUP_MENU 4 · GROUP_BTN 20 · I18N 3
SELECT '1.MENU' AS AREA, COUNT(*) AS CNT FROM SCM_ADM_MNU_M WHERE MNU_ID = '&V_MENU_ID'
UNION ALL SELECT '1.I18N', COUNT(*) FROM SCM_ADM_MSG_M WHERE MSG_ID = '&V_MENU_MSG_ID'
UNION ALL SELECT '2.PROC_M', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '&V_PKG_NM' || '.%'
UNION ALL SELECT '3.SHEET_COLUMNS', COUNT(*) FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID = '&V_MENU_ID'
UNION ALL SELECT '5.API', COUNT(*) FROM SCM_ADM_API_M WHERE API_ID IN ('P_SCP0096_GET', 'P_SCP0096_SAVE', 'SCP0009_SHEET_CALENDAR_3SPAN_GET', 'SCM0001_SCP_MONTH_PERIOD_GET')
UNION ALL SELECT '6.MNU_BTN_MPG', COUNT(*) FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID = '&V_MENU_ID'
UNION ALL SELECT '7.GROUP_MENU', COUNT(*) FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID = '&V_MENU_ID'
UNION ALL SELECT '7.GROUP_BTN', COUNT(*) FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID = '&V_MENU_ID' ORDER BY 1;
DECLARE v_cur SYS_REFCURSOR; v_proc VARCHAR2(200); v_col VARCHAR2(100); v_dt VARCHAR2(50); v_ct VARCHAR2(50); v_so NUMBER; v_cnt NUMBER := 0;
BEGIN
  SCM_MGR.PKG_NSCM_UI_COMM.PR_GET_PROC_INFO_LIST(P_MNU_ID => '&V_MENU_ID', P_SHT_NM => 'Shipment Working Day OSP', P_MNU_BTN_CD => 'SEARCH', O_CURSOR => v_cur);
  LOOP FETCH v_cur INTO v_proc, v_col, v_dt, v_ct, v_so; EXIT WHEN v_cur%NOTFOUND; v_cnt := v_cnt + 1; END LOOP; CLOSE v_cur;
  DBMS_OUTPUT.PUT_LINE('SEARCH 라우팅: ' || CASE WHEN v_cnt = 0 THEN 'FAIL 라우팅 없음' WHEN v_cnt < 6 THEN 'WARN PROC_M ' || v_cnt || '행(기대 6)' ELSE 'OK 파라미터 ' || v_cnt END);
  v_cnt := 0;
  SCM_MGR.PKG_NSCM_UI_COMM.PR_GET_PROC_INFO_LIST(P_MNU_ID => '&V_MENU_ID', P_SHT_NM => 'dayRange', P_MNU_BTN_CD => 'SEARCH', O_CURSOR => v_cur);
  LOOP FETCH v_cur INTO v_proc, v_col, v_dt, v_ct, v_so; EXIT WHEN v_cur%NOTFOUND; v_cnt := v_cnt + 1; END LOOP; CLOSE v_cur;
  DBMS_OUTPUT.PUT_LINE('dayRange 라우팅: ' || CASE WHEN v_cnt = 0 THEN 'FAIL 라우팅 없음' WHEN v_cnt < 7 THEN 'WARN PROC_M ' || v_cnt || '행(기대 7)' ELSE 'OK 파라미터 ' || v_cnt END);
END;
/
-- COMMIT;   -- BLOCK 8 확인 후 수동 커밋 (롤백: ROLLBACK;)
UNDEFINE V_MENU_ID V_MENU_MSG_ID V_MENU_URL V_PKG_NM V_USER_ID
